<template>
 <div><div class="designer-heading"><div><h1>Switches</h1><p>Assign a saved front-panel design to a physical switch.</p></div><NuxtLink class="btn" to="/switch-designer">Visual Switch Designer</NuxtLink></div>
 <p v-if="error" class="danger panel">{{error}}</p><p v-if="notice" class="success-note">{{notice}}</p>
 <section class="panel"><h2>Add physical switch</h2><div class="form"><label>Switch name</label><input v-model="name" maxlength="120" placeholder="Core-SW-01"><label>Building</label><select v-model="buildingId"><option value="">Select building…</option><option v-for="b in buildings" :key="b.id" :value="b.id">{{b.name}}</option></select><label>Front-panel template</label><select v-model="templateId"><option value="">Select template…</option><option v-for="t in templates" :key="t.id" :value="t.id">{{t.name}}</option></select><label>Hostname (optional)</label><input v-model="hostname" placeholder="core-sw-01"><label>Management IP (optional)</label><input v-model="managementIp" placeholder="192.168.1.10"><button class="btn" :disabled="!isAdmin||saving||!name.trim()||!buildingId||!templateId" @click="createSwitch">{{saving?'Saving…':'Create switch and ports'}}</button></div><p v-if="!isAdmin" class="muted">Administrator access is required to create switches.</p></section>
 <section class="panel"><h2>Installed switches</h2><p v-if="loading">Loading…</p><p v-else-if="!switches.length" class="muted">No switches yet.</p><div v-for="sw in switches" :key="sw.id" class="installed-switch"><div class="designer-heading"><div><strong>{{sw.name}}</strong><p>{{buildingName(sw.building_id)}} · {{sw.hostname||'No hostname'}} · {{sw.management_ip||'No management IP'}}</p></div><button class="small-btn" @click="expanded=expanded===sw.id?'':sw.id">{{expanded===sw.id?'Hide ports':'Show ports'}}</button></div><div v-if="expanded===sw.id"><div class="compact-switch" :style="{backgroundColor:templateFor(sw)?.face_color||'#263344'}"><div v-for="g in layoutGroups(templateFor(sw)?.layout)" :key="g.id" class="compact-group"><strong>{{g.title}}</strong><div class="compact-ports" :style="{gridTemplateColumns:`repeat(${g.columns}, 28px)`}"><button v-for="n in g.count" :key="n" class="face-port" :class="{'fiber-port':g.type!=='RJ45'}" @click="choosePort(sw.id,g,n)"><span class="port-number">{{g.start+n-1}}</span><span class="port-hole">{{g.type==='RJ45'?'▥':'▭'}}</span></button></div></div></div><div v-if="selected?.switchId===sw.id" class="port-detail"><h3>Port {{selected.port.label}} ({{selected.port.port_type}})</h3><label>VLAN ID (optional)</label><input v-model="portVlan" type="number" min="1" max="4094" placeholder="1–4094"><label>Description</label><input v-model="portDescription" maxlength="300" placeholder="Connected device or outlet"><button class="btn" :disabled="!isAdmin||saving" @click="savePort">Save port details</button></div></div></div></section>
 </div>
</template>
<script setup lang="ts">
definePageMeta({middleware:'auth'});const client=useSupabaseClient();const {isAdmin,refreshRole}=useAccess()
const name=ref(''),hostname=ref(''),managementIp=ref(''),buildingId=ref(''),templateId=ref(''),error=ref(''),notice=ref(''),saving=ref(false),loading=ref(true)
const buildings=ref<any[]>([]),templates=ref<any[]>([]),switches=ref<any[]>([]),ports=ref<any[]>([]),expanded=ref(''),selected=ref<{switchId:string;port:any}|null>(null),portVlan=ref(''),portDescription=ref('')
const layoutGroups=(layout:any)=>Array.isArray(layout)?layout:(layout?.groups||[])
const buildingName=(id:string)=>buildings.value.find(x=>x.id===id)?.name||'Unknown building';const templateFor=(sw:any)=>templates.value.find(x=>x.id===sw.template_id)
async function load(){loading.value=true;const results=await Promise.all([client.from('buildings').select('id,name').order('name'),client.from('switch_templates').select('*').order('name'),client.from('network_switches').select('*').order('name'),client.from('switch_ports').select('*')]);error.value=results.find(r=>r.error)?.error?.message||'';buildings.value=results[0].data||[];templates.value=results[1].data||[];switches.value=results[2].data||[];ports.value=results[3].data||[];loading.value=false}
async function createSwitch(){if(!isAdmin.value)return;const t=templates.value.find(x=>x.id===templateId.value);if(!t)return;error.value='';notice.value='';saving.value=true;const {data:sw,error:e}=await client.from('network_switches').insert({name:name.value.trim(),building_id:buildingId.value,template_id:templateId.value,hostname:hostname.value.trim(),management_ip:managementIp.value.trim()}).select('id').single();if(e){error.value=e.message;saving.value=false;return}const records=layoutGroups(t.layout).flatMap((g:any)=>Array.from({length:g.count},(_,i)=>({switch_id:sw.id,port_key:`${g.id}:${i}`,label:String(g.start+i),port_type:g.type})));const {error:portError}=records.length?await client.from('switch_ports').insert(records):{error:null};if(portError){await client.from('network_switches').delete().eq('id',sw.id);error.value='Could not create ports: '+portError.message}else{notice.value='Switch and '+records.length+' ports created.';name.value='';hostname.value='';managementIp.value='';await load()}saving.value=false}
function choosePort(switchId:string,g:any,n:number){const port=ports.value.find(x=>x.switch_id===switchId&&x.port_key===`${g.id}:${n-1}`);if(!port){error.value='Port record not found';return}selected.value={switchId,port};portVlan.value=port.vlan_id==null?'':String(port.vlan_id);portDescription.value=port.description||''}
async function savePort(){if(!selected.value||!isAdmin.value)return;const vlan=portVlan.value.trim()===''?null:Number(portVlan.value);if(vlan!==null&&(!Number.isInteger(vlan)||vlan<1||vlan>4094)){error.value='VLAN must be 1–4094';return}saving.value=true;error.value='';const {error:e}=await client.from('switch_ports').update({vlan_id:vlan,description:portDescription.value.trim()}).eq('id',selected.value.port.id);if(e)error.value=e.message;else{notice.value='Port details saved.';await load()}saving.value=false}
onMounted(async()=>{await refreshRole();await load()})
</script>
